import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25, C: 33.33, D: 0.1, E: 100, F: 101 }
const pricing = { priceOf: async (sku) => prices[sku] }

async function withApp(fn) {
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  const base = `http://localhost:${server.address().port}`
  try { return await fn(base) } finally { server.close() }
}

async function totalFor(items) {
  return withApp(async (base) => {
    const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
    assert.equal(res.status, 201)
    const order = await res.json()
    const fetched = await (await fetch(`${base}/orders/${order.id}`)).json()
    assert.equal(fetched.total, order.total)
    return order.total
  })
}

// Characterization: pins current behavior (10% off when subtotal > 100, result floored to whole euros).
const cases = [
  ['single item, no discount', [{ sku: 'A', qty: 1 }], 10],
  ['multiple items, no discount', [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }], 70],
  ['subtotal exactly 100 gets no discount', [{ sku: 'E', qty: 1 }], 100],
  ['subtotal 101 is discounted (90.9 floored)', [{ sku: 'F', qty: 1 }], 90],
  ['subtotal 110 discounted', [{ sku: 'A', qty: 11 }], 99],
  ['large order 1000 -> 900', [{ sku: 'A', qty: 100 }], 900],
  ['fractional prices, no discount floors (99.99 -> 99)', [{ sku: 'C', qty: 3 }], 99],
  ['fractional discounted (166.65*0.9=149.985 -> 149)', [{ sku: 'C', qty: 5 }], 149],
  ['mixed items with discount', [{ sku: 'B', qty: 3 }, { sku: 'C', qty: 2 }, { sku: 'A', qty: 1 }], 134],
  ['float sum 0.1 x 3 floors to 0', [{ sku: 'D', qty: 3 }], 0],
]
for (const [name, items, expected] of cases) {
  test(name, async () => assert.equal(await totalFor(items), expected))
}
EOF
